// One command keeps every generated card current (owner, 2026-10-19: "the self card needs to update entirely with every new build, along with the
// book and any other relevant cards ... we need an automatic system"). The book, the families, the dependency map, the skill index and Verse's
// facts about itself are all derived from the skills and the ledgers; each used to be regenerated by hand in whatever order the author remembered,
// and deploy.yml listed only some of them, so a merge could leave a card stale on the live site. Now there is one ordered list, and three callers
// share it: deploy.yml (regenerates all before every deploy), tools/checks.mjs (fails when any is stale) and whoever changes a skill.
//
//   node tools/refresh.mjs                 regenerate everything, in order, stopping at the first one that fails
//   node tools/refresh.mjs --check         say which committed ones are stale and exit 1 if any (writes nothing); --all adds the volatile ones
//   node tools/refresh.mjs --keep-going    regenerate everything even when one step fails (what the deploy runs: a stale card never blocks a deploy, and never hides the others)
//   node tools/refresh.mjs --only a,b      just those steps, still in order
//   node tools/refresh.mjs --list          the steps and why they come in this order
// A new generated file is one more row in STEPS, with a --check that exits 1 when it is stale; tools/refresh.test.mjs fails when deploy.yml does not call this.
import { spawnSync } from 'node:child_process';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));

/** in dependency order: a step reads what the steps above it wrote. */
export const STEPS = [
  { name: 'index', script: 'skills-index.mjs', write: ['--write'], check: ['--check'], why: 'the routing order the page loads, from skills/order/' },
  { name: 'deps', script: 'deps.mjs', write: [], check: ['--check'], why: 'who imports whom, from the files themselves' },
  { name: 'families', script: 'families.mjs', write: [], check: ['--check'], why: 'each skill\'s family and how far it is proven, from the tests and the benchmark' },
  { name: 'guide', script: 'guide.mjs', write: [], check: ['--check'], why: 'the book: one page per skill, game and miniature, from the skills and the families' },
  { name: 'what', script: 'what-skills.mjs', write: [], check: ['--check'], why: 'one current line per skill for the cards that list them (the already-built card), from the book' },
  { name: 'seo', script: 'seo-pages.mjs', write: [], check: ['--check'], why: 'each tool page\'s canonical link and JSON-LD, from the table in lib/seo.js (what the page is, the words people search for it)' },
  { name: 'parity', script: 'parity.mjs', write: ['--write'], check: ['--check'], why: 'each obituary site\'s feature inventory (docs/PARITY), /parity.json and the cited timelines /obituaries/ opens, from the pages, the tower and docs/HISTORY; no network (the live scan is node tools/parity.mjs --scan)' },
  { name: 'tower-plan', script: 'tower-plan.mjs', write: [], check: ['--check'], why: "the Versus card's plan (working on now, next easiest, far future), from the tower-plan block in docs/NEXT.md; every id checked against the tower's floors" },
  { name: 'asks', script: 'asks-link.mjs', write: ['--write'], check: ['--check'], volatile: true, why: "which of Verse's asks are built, linked to the ledger line that built them (the wants and self cards list only the rest); a new ledger line can answer an old ask, so the deploy links them" },
  { name: 'self', script: 'self-context.mjs', write: [], check: ['--check'], volatile: true, why: "Verse's facts about itself (the self card, /api/answer), from everything above and the ledgers; it embeds the newest commits, so only the deploy keeps it current" },
  { name: 'bench-alarms', script: 'bench-alarms.mjs', write: [], check: ['--check'], volatile: true, why: "the Bench icon's count of checked false alarms; regenerated at deploy" },
  { name: 'churn', script: 'churn.mjs', write: ['--write'], check: ['--check'], volatile: true, why: "churn.json: the files changed more than 12 times in 7 days, from git; the will skips a want that names one, and only the deploy keeps the window current" },
  { name: 'sitemap', script: 'sitemap.mjs', write: [], check: ['--check'], volatile: true, why: 'sitemap.xml: the home page, every tool page, the tower, the /fix/ and /is-it/ pages, lastmod from git; the deploy sets the dates' },
];

/** the steps picked by name, in STEPS order; an unknown name is an error. Pure. */
export function pick(names) {
  if (!names || !names.length) return STEPS.slice();
  const bad = names.filter((n) => !STEPS.some((s) => s.name === n));
  if (bad.length) throw new Error('unknown step: ' + bad.join(', ') + ' (steps: ' + STEPS.map((s) => s.name).join(', ') + ')');
  return STEPS.filter((s) => names.includes(s.name));
}

/** run one step; { name, ok, out } */
export function runStep(step, mode, cwd = resolve(here, '..')) {
  const r = spawnSync(process.execPath, [resolve(here, step.script), ...(mode === 'check' ? step.check : step.write)], { cwd, encoding: 'utf8', timeout: 120000 });
  return { name: step.name, ok: r.status === 0, out: ((r.stdout || '') + (r.stderr || '')).trim().split('\n').slice(-1)[0] || '' };
}

function main(argv) {
  if (argv.includes('--list')) { for (const s of STEPS) console.log(s.name.padEnd(13) + s.why); return 0; }
  const i = argv.indexOf('--only'), steps = pick(i >= 0 ? String(argv[i + 1] || '').split(',').filter(Boolean) : []);
  const check = argv.includes('--check'), keep = argv.includes('--keep-going'), all = argv.includes('--all'), stale = [];
  for (const s of steps) {
    if (check && s.volatile && !all && i < 0) { console.log('skip  ' + s.name.padEnd(13) + 'volatile: the deploy regenerates it'); continue; }
    const r = runStep(s, check ? 'check' : 'write');
    console.log((r.ok ? 'ok    ' : 'FAIL  ') + s.name.padEnd(13) + r.out.slice(0, 110));
    if (!r.ok) { stale.push(s.name); if (!check && !keep) break; }
  }
  if (stale.length) { console.error(check ? 'stale: ' + stale.join(', ') + ' (run node tools/refresh.mjs)' : 'refresh stopped at ' + stale[0]); return 1; }
  return 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exit(main(process.argv.slice(2)));
